// Raster-Komponente für Produkte
const ProductGrid = React.memo(
  ({ products, loading, error, onLike, onDislike, likedProducts, loadMore, hasMore, showMore, setShowMore }) => {
    const observer = useRef();
    const lastProductRef = useCallback(
      (node) => {
        if (loading || !hasMore) return;
        if (observer.current) observer.current.disconnect();
        observer.current = new IntersectionObserver(
          (entries) => {
            if (entries[0].isIntersecting) loadMore();
          },
          { rootMargin: '100px' }
        );
        if (node) observer.current.observe(node);
      },
      [loading, hasMore, loadMore]
    );

    if (loading && !products.length) {
      return (
        <div className="flex flex-col items-center justify-center py-16 min-h-[400px] bg-gray-50/50 rounded-lg">
          <Loader2 className="w-12 h-12 text-blue-600 animate-spin mb-4" />
          <span className="text-gray-700 text-lg font-medium">Geschenke werden geladen...</span>
        </div>
      );
    }

    if (error) return <Alert>{error}</Alert>;

    if (!products.length)
      return (
        <div className="text-center py-16 min-h-[400px] bg-gray-50/50 rounded-lg border border-gray-200">
          <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <p className="text-gray-700 text-lg font-medium mb-2">Keine Geschenke gefunden</p>
          <p className="text-gray-500">Versuche es mit anderen Filtereinstellungen</p>
        </div>
      );

    const initialProducts = products.slice(0, 8);

    return (
      <div className="flex flex-col items-center min-h-[400px]">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 w-full">
          {(showMore ? products : initialProducts).map((p, index) => (
            <div
              key={p.id}
              ref={index === (showMore ? products.length : initialProducts.length) - 1 ? lastProductRef : null}
            >
              <ProductCard
                product={p}
                onLike={onLike}
                onDislike={onDislike}
                likedProducts={likedProducts}
              />
            </div>
          ))}
        </div>
        {!showMore && products.length > 8 && setShowMore && (
          <div className="mt-10">
            <button
              onClick={() => setShowMore(true)}
              className="px-6 py-3 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-all duration-300 focus:outline-none font-medium flex items-center shadow-md"
            >
              <Sparkles className="w-5 h-5 mr-2" />
              Weitere Geschenke anzeigen
            </button>
          </div>
        )}
        {loading && showMore && (
          <div className="py-8">
            <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
          </div>
        )}
      </div>
    );
  }
);

